/**
 * GET /og.png
 * Generates the aQross social preview card as a 1200×630 PNG.
 * Uses @vercel/og (Node renderer) + satori for layout.
 * No JSX — uses React.createElement so no transpiler needed in Nitro.
 */
import { defineEventHandler, setHeader } from "h3";
import { createElement as h } from "react";
import { ImageResponse } from "@vercel/og";

// Logo embedded as base64 so it's available at edge without fs access
const LOGO_DATA_URL = "data:image/png;base64,";

// Brand colours
const BRAND = "#F4510B";
const WHITE = "#ffffff";
const DARK = "#1a1a1a";
const MUTED = "#888888";
const SURFACE = "#f5f5f5";

export default defineEventHandler(async () => {
  const element = h(
    "div",
    {
      style: {
        width: "1200px",
        height: "630px",
        display: "flex",
        background: WHITE,
        fontFamily: "'Poppins', system-ui, sans-serif",
        padding: "0",
        position: "relative",
        overflow: "hidden",
      },
    },

    // ── Subtle top-left orange bar ────────────────────────────────
    h("div", {
      style: {
        position: "absolute",
        left: "0",
        top: "40px",
        width: "6px",
        height: "550px",
        background: BRAND,
        borderRadius: "0 4px 4px 0",
        opacity: "0.75",
      },
    }),

    // ── Neumorphic card ───────────────────────────────────────────
    h(
      "div",
      {
        style: {
          position: "absolute",
          left: "40px",
          top: "40px",
          width: "1120px",
          height: "550px",
          background: "#f8f8f8",
          borderRadius: "48px",
          boxShadow:
            "12px 12px 32px rgba(0,0,0,0.07), -12px -12px 32px rgba(255,255,255,0.9)",
          display: "flex",
          overflow: "hidden",
        },
      },

      // ── LEFT COLUMN ─────────────────────────────────────────────
      h(
        "div",
        {
          style: {
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            padding: "60px 56px",
            width: "540px",
            flexShrink: "0",
          },
        },

        // Logo
        h("img", {
          src: LOGO_DATA_URL,
          width: 300,
          height: 90,
          style: { objectFit: "contain", objectPosition: "left center", marginBottom: "24px" },
        }),

        // Divider
        h("div", {
          style: {
            width: "380px",
            height: "2px",
            background: BRAND,
            opacity: "0.2",
            marginBottom: "24px",
            borderRadius: "2px",
          },
        }),

        // Headline
        h(
          "div",
          {
            style: {
              fontSize: "28px",
              fontWeight: "700",
              color: DARK,
              lineHeight: "1.25",
              marginBottom: "12px",
              letterSpacing: "-0.5px",
            },
          },
          "Shop & Delivery for Students"
        ),

        // Sub text
        h(
          "div",
          {
            style: {
              fontSize: "17px",
              fontWeight: "400",
              color: MUTED,
              lineHeight: "1.5",
              marginBottom: "36px",
            },
          },
          "Groceries · Stationery · Pharma — Campus Fast"
        ),

        // CTA pill
        h(
          "div",
          {
            style: {
              display: "flex",
              alignItems: "center",
              background: BRAND,
              color: WHITE,
              borderRadius: "24px",
              padding: "12px 28px",
              fontSize: "16px",
              fontWeight: "700",
              width: "fit-content",
              marginBottom: "32px",
            },
          },
          "aqcoss.co.ke"
        ),

        // Stat pills row
        h(
          "div",
          { style: { display: "flex", gap: "12px" } },

          ...(
            [
              ["15–45 min", "Delivery"],
              ["Student", "Deals"],
              ["Verified", "Shops"],
            ] as [string, string][]
          ).map(([top, bot]) =>
            h(
              "div",
              {
                key: top,
                style: {
                  display: "flex",
                  flexDirection: "column",
                  alignItems: "center",
                  justifyContent: "center",
                  background: WHITE,
                  borderRadius: "14px",
                  padding: "8px 16px",
                  boxShadow:
                    "4px 4px 10px rgba(0,0,0,0.06), -4px -4px 10px rgba(255,255,255,0.85)",
                  minWidth: "90px",
                },
              },
              h("div", { style: { fontSize: "12px", fontWeight: "700", color: BRAND } }, top),
              h("div", { style: { fontSize: "10px", fontWeight: "500", color: MUTED } }, bot)
            )
          )
        )
      ),

      // ── DASHED DIVIDER ──────────────────────────────────────────
      h("div", {
        style: {
          position: "absolute",
          left: "560px",
          top: "60px",
          width: "1.5px",
          height: "430px",
          background:
            "repeating-linear-gradient(to bottom, #e0e0e0 0px, #e0e0e0 6px, transparent 6px, transparent 10px)",
        },
      }),

      // ── RIGHT COLUMN: basket ────────────────────────────────────
      h(
        "div",
        {
          style: {
            flex: "1",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            position: "relative",
          },
        },

        // Orange ambient glow
        h("div", {
          style: {
            position: "absolute",
            width: "400px",
            height: "400px",
            borderRadius: "50%",
            background:
              "radial-gradient(circle, rgba(244,81,11,0.10) 0%, transparent 70%)",
          },
        }),

        // Neumorphic circle behind basket
        h("div", {
          style: {
            position: "absolute",
            width: "360px",
            height: "360px",
            borderRadius: "50%",
            background: SURFACE,
            boxShadow:
              "10px 10px 28px rgba(0,0,0,0.06), -10px -10px 28px rgba(255,255,255,0.85)",
          },
        }),

        // Basket image from deployed URL
        h("img", {
          src: "https://aqcoss.co.ke/3ce0b937-e727-4591-b5fa-8a8eac6f3d1b.png",
          width: 320,
          height: 280,
          style: { objectFit: "contain", position: "relative", zIndex: "2" },
        }),

        // Bottom veil — basket fades into white
        h("div", {
          style: {
            position: "absolute",
            bottom: "0",
            left: "0",
            right: "0",
            height: "180px",
            background:
              "linear-gradient(to top, rgba(248,248,248,1) 0%, rgba(248,248,248,0.6) 50%, transparent 100%)",
            zIndex: "3",
          },
        })
      )
    )
  );

  const response = new ImageResponse(element as never, {
    width: 1200,
    height: 630,
  });

  return new Response(await response.arrayBuffer(), {
    headers: {
      "Content-Type": "image/png",
      "Cache-Control": "public, max-age=86400, stale-while-revalidate=604800",
    },
  });
});
